      "severity": "MEDIUM",
      "explanation": "The RDP ingress rule has no description, making its purpose and intended access path harder to identify during security reviews and incident response."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP is exposed to the public internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The rule permits TCP port 3389 from 0.0.0.0/0, exposing Windows RDP to internet-wide scanning, brute-force attempts, and exploitation."
    }
  ],
  "patched_code": "variable "rdp_allowed_cidr_blocks" {
  description = "Trusted IPv4 CIDR blocks permitted to access RDP."
  type        = list(string)

  validation {
    condition = (
      length(var.rdp_allowed_cidr_blocks) > 0 &&
      alltrue([for cidr in var.rdp_allowed_cidr_blocks : cidr != "0.0.0.0/0"])
    )
    error_message = "At least one trusted CIDR must be provided, and 0.0.0.0/0 is not permitted for RDP access."
  }
}

resource "aws_security_group_rule" "changeme_remote_exec_inline_security_group_rule_incoming_rdp" {
  description       = "Allow RDP access from trusted IPv4 networks"
  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id
  type              = "ingress"
  from_port         = 3389
  to_port           = 3389
  protocol          = "tcp"
  cidr_blocks       = var.rdp_allowed_cidr_blocks
}
",
  "fix_summary": "Added a descriptive label to the security group rule and replaced unrestricted RDP access with a required list of trusted CIDR blocks. Input validation prevents configuring 0.0.0.0/0 and requires at least one approved source."
